static const size_t font_count = sizeof(font_table) / sizeof(font_table[0]);

/* 
const == 変更不可
uint8_t == 固定長8ビット符号なし整数 今回の場合は、FontData配列のvalue値の先頭8bit
* == アドレス
*font_get == この関数はポインタを返す
(const char *character) == 引数は変更不可、charは1byteなので、ポインタを受け取る
font_get関数にUTF-8文字列を渡す

font_get("あ");
character
   ↓
┌────┬────┬────┐
│ E3 │ 81 │ 82 │
└────┴────┴────┘
*/
static const uint8_t *font_get_bycode(const uint16_t code) {
    if(code == 0)return NULL;
    //二分探索開始
    size_t low = 0; //探索範囲の先頭側
    size_t high = font_count; //探索範囲の末尾の次
    while(low < high){
        size_t mid = low + (high - low)/2;
        if(font_table[mid].code == code) {
            return font_table[mid].data;
        }else if(font_table[mid].code < code) low = mid + 1;
        else high = mid;
    }
    return NULL;
}

//指定ピクセルは０か１かを出力
static bool pixelset_8px_Misaki(const void *data, size_t x, size_t y, size_t offset){
    const uint8_t *rows = data;
    if(x >= 8 || y >= 8) return false;
    return (rows[y] & (0x80 >> (x + offset))) != 0;
}

//構造体FontGlyphに該当コードポイントのドットデータと情報を代入
bool get_glyph_8px_misaki(uint16_t codepoint, FontGlyph *out){
    if(out == NULL) {
        return false;
    }

    const uint8_t *rows = font_get_bycode(codepoint);
    if(rows == NULL) {
        return false;
    }
    if((0x0020 <= codepoint && codepoint <= 0x007E)//ASCII文字(半角英数記号)
        ||(0xff61 <= codepoint && codepoint <= 0xff9f))//半角カタカナ
        {
            out->width = Font_8px_Misaki_info.width_halffont;
        } else {
            out->width = Font_8px_Misaki_info.width; //それ以外は全角
        }
    out->height = Font_8px_Misaki_info.height;
    out->data = rows;
    out->pixelset = pixelset_8px_Misaki;
    
    return true;
}



